// Transactions Page
// Dedicated page for managing transactions
// Add, view, delete, and filter transactions

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from '../components/Navbar';
import TransactionForm from '../components/TransactionForm';
import TransactionList from '../components/TransactionList';
import TransactionFilter from '../components/TransactionFilter';
import './TransactionsPage.css';

function TransactionsPage() {
  const [transactions, setTransactions] = useState([]);
  const [filteredTransactions, setFilteredTransactions] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(true);

  const token = localStorage.getItem('token');

  // Fetch transactions when page loads
  useEffect(() => {
    fetchTransactions();
  }, []);

  const fetchTransactions = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:5000/api/transactions', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(response.data);
    } catch (error) {
      console.log('Error fetching transactions:', error.message);
    } finally {
      setLoading(false);
    }
  };

  // Called after adding a transaction
  const handleTransactionAdded = () => {
    fetchTransactions();
    setShowForm(false);
  };

  // Handle filter changes
  const handleFilterChange = (filteredData) => {
    if (filteredData === null) {
      setFilteredTransactions(null);
    } else {
      setFilteredTransactions(filteredData);
    }
  };

  // Delete a transaction
  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/transactions/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(transactions.filter(t => t.id !== id));
    } catch (error) {
      console.log('Error deleting transaction:', error.message);
    }
  };

  // Calculate totals
  const displayTransactions = filteredTransactions !== null ? filteredTransactions : transactions;
  const totalIncome = displayTransactions
    .filter(t => t.type === 'income')
    .reduce((sum, t) => sum + parseFloat(t.amount), 0);

  const totalExpense = displayTransactions
    .filter(t => t.type === 'expense')
    .reduce((sum, t) => sum + parseFloat(t.amount), 0);

  const balance = totalIncome - totalExpense;

  return (
    <div className="transactions-page">
      <Navbar />

      {/* Header */}
      <div className="transactions-header">
        <h1>💳 Transactions</h1>
        <p>Manage all your income and expense transactions</p>
      </div>

      {/* Summary Cards */}
      <div className="transactions-summary">
        <div className="summary-card income-card">
          <div className="card-icon">📈</div>
          <div className="card-content">
            <h3>Total Income</h3>
            <p className="card-amount">₹ {totalIncome.toFixed(2)}</p>
          </div>
        </div>

        <div className="summary-card expense-card">
          <div className="card-icon">📉</div>
          <div className="card-content">
            <h3>Total Expense</h3>
            <p className="card-amount">₹ {totalExpense.toFixed(2)}</p>
          </div>
        </div>

        <div className="summary-card balance-card">
          <div className="card-icon">💳</div>
          <div className="card-content">
            <h3>Balance</h3>
            <p className="card-amount">₹ {balance.toFixed(2)}</p>
          </div>
        </div>
      </div>

      {/* Filter Section */}
      <div className="transactions-filter-section">
        <h2>🔍 Filter Transactions</h2>
        <TransactionFilter onFilterChange={handleFilterChange} />
      </div>

      {/* Add Transaction Section */}
      <div className="add-transaction-section">
        <div className="section-header">
          <h2>➕ Add New Transaction</h2>
          <button
            className="toggle-form-btn"
            onClick={() => setShowForm(!showForm)}
          >
            {showForm ? '✕ Cancel' : '+ Add Transaction'}
          </button>
        </div>
        {showForm && (
          <TransactionForm onTransactionAdded={handleTransactionAdded} />
        )}
      </div>

      {/* Transactions List */}
      <div className="transactions-list-section">
        <h2>📋 {filteredTransactions !== null ? 'Filtered Transactions' : 'All Transactions'}</h2>
        {loading ? (
          <div className="loading-message">Loading transactions...</div>
        ) : displayTransactions.length === 0 ? (
          <div className="empty-message">No transactions found. Add one to get started!</div>
        ) : (
          <TransactionList
            transactions={displayTransactions}
            onDelete={handleDelete}
            heading=""
          />
        )}
      </div>
    </div>
  );
}

export default TransactionsPage;
